scwin.form_authFormForm = { action: "", method: 'post', target: '' };

scwin.form_userForm = { action: "", method: 'post', target: '' };

scwin.form_allFormForm = { action: "", method: 'post', target: '' };

try { scwin.selAuthFormCdList =[]; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'uldmgt50400' }); }

try { scwin.selAuthFormVerList =[]; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'uldmgt50400' }); }

try { scwin.selAuthFormInfo =[]; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'uldmgt50400' }); }

try { scwin.selFormList =[]; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'uldmgt50400' }); }

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
        scwin.init_fillGen();
    } catch (e) {
        $c.exception.handleError(e, { context: 'uldmgt50400.onpageload' });
    }
};

