/**
 * @method
 * @name grd_formAuths_2_oncellclick
 * @description grd_formAuths_2 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_formAuths_2_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_formAuths');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_formAuths */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        scwin.addAuth(); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_formAuths_2.oncellclick' });
    }
};

