/**
 * @method
 * @name findContent
 * @description find Content 처리
 * @param {*} _method _method
 * @param {*} _dataDiv _dataDiv
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.findContent = async function (_method, _dataDiv) {
    scwin.form_authForm.action = "/filing/byauthForm.do";
    $c.util.getComponent('dma_findContentXhrReq').set('method', _method);
    dataDiv = _dataDiv;
    await scwin.tx_findContent_xhr();
};

/**
 * @method
 * @name onCompleteResponse
 * @description on Complete Response 처리
 * @param {*} responseText responseText
 * @returns {void}
 * @hidden N
 */
scwin.onCompleteResponse = function (responseText) {
    ($c.util.getComponent("document.all." + dataDiv) && $c.util.getComponent("document.all." + dataDiv).setValue) ? $c.util.getComponent("document.all." + dataDiv).setValue(responseText) : (($c.util.getComponent("document.all." + dataDiv) && $c.util.getComponent("document.all." + dataDiv).setText) ? $c.util.getComponent("document.all." + dataDiv).setText(responseText) : (console.warn('[sdd] 값 쓰기 미지원 컴포넌트: ' + "document.all." + dataDiv), void (responseText)));
};

/**
 * @method
 * @name findAuthContent
 * @description find Auth Content 처리
 * @param {String} formAuthId formAuthId
 * @param {String} formAuthNm formAuthNm
 * @param {Number} cnt cnt
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.findAuthContent = async function (formAuthId, formAuthNm, cnt) {
    $c.util.getComponent('dma_findContentXhrReq').set('formAuthId', formAuthId);
    $c.util.getComponent('dma_findContentXhrReq').set('formAuthNm', formAuthNm);
    let msgStr = "대상 권한의 권한서식 정보 및 User 정보를 조회합니다.\n";
    msgStr += "===============================================\n";
    msgStr += " 대상 권한 : [" + $c.util.getComponent('dma_findContentXhrReq').get('formAuthNm') + "]\n";
    msgStr += "===============================================\n\n";
    msgStr += "조회하시겠습니까?";
    if (await $c.win.confirm(msgStr)) {
        scwin.formAuthSearchYn = true;
        await scwin.findAuthUser(formAuthId);
        await scwin.findAuthForm(formAuthId);
        $(".Auth_list").find("a").css("color", "black");
        $(".Auth_list_" + cnt).find("a").css("color", "blue");
        $(".cur_auth_title").html("<span style='color:yellow; font-size:7.5pt;'>" + formAuthId + ", " + formAuthNm + "</span>");
    } else {
        await $c.win.alert("조회를 취소합니다.");
        return;
    }
};

/**
 * @method
