    scwin.form_authFormForm.action = "/filing/byauthForm.do";
    $c.util.getComponent('dma_findContentXhrReq').set('method', "findAuthForm");
    $c.util.getComponent('dma_findContentXhrReq').set('formAuthId', formAuthId);
    dataDiv = "authFormDiv";
    await scwin.tx_findAuthForm_xhr();
};

