/**
 * @method
 * @name search
 * @description search 처리
 * @param {String} searchTp searchTp
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function (searchTp) {
    scwin.formAuthSearchYn = scwin.checkFormAuthSearchYn();
    if (searchTp === 'auth') {
        let msgStr = "권한 서식 List 내의 서식 정보를 조회합니다.\n";
        msgStr += "===============================================\n";
        if (scwin.formAuthSearchYn) {
            msgStr += " 대상 권한 : [" + $c.util.getComponent('dma_findContentXhrReq').get('formAuthNm') + "]\n";
        } else {
            msgStr += " 선택 권한 : [" + $(".copyAuthList option:selected").text() + "]\n";
        }
        msgStr += " 검색어 : [" + $c.util.getComponent('ipt_authFormNm').getValue()+ "]\n\n";
        msgStr += "===============================================\n\n";
        msgStr += "조회하시겠습니까?";
        if (await $c.win.confirm(msgStr)) {
            $c.util.getComponent('dma_findContentXhrReq').set('ldMktTpCd', $c.util.getComponent('slc_ldMktTpCd1').getValue());
            $c.util.getComponent('dma_findContentXhrReq').set('searchFormNm', $c.util.getComponent('ipt_authFormNm').getValue());
            await scwin.findAuthForm($c.util.getComponent('dma_findContentXhrReq').get('formAuthId'));
        } else {
            await $c.win.alert("조회를 취소합니다.");
            return;
        }
    } else {
        if (searchTp === 'all') {
            msgStr = "전체 서식 List 내의 서식 정보를 조회합니다.\n";
            msgStr += "===============================================\n";
            msgStr += " 검색어 : [" + $c.util.getComponent('ipt_formNm').getValue()+ "]\n\n";
            msgStr += "===============================================\n\n";
            msgStr += "조회하시겠습니까?";
            if (await $c.win.confirm(msgStr)) {
                $c.util.getComponent('dma_findContentXhrReq').set('ldMktTpCd', $c.util.getComponent('slc_ldMktTpCd2').getValue());
                $c.util.getComponent('dma_findContentXhrReq').set('searchFormNm', $c.util.getComponent('ipt_formNm').getValue());
                await scwin.findFormList();
            } else {
                await $c.win.alert("조회를 취소합니다.");
                return;
            }
        }
    }
};

