/**
 * @method
 * @name selAuthFormCount
 * @description sel Auth Form Count 처리
 * @returns {void}
 * @hidden N
 */
scwin.selAuthFormCount = function () {
    scwin.selAuthFormCdList = [];
    scwin.selAuthFormVerList = [];
    scwin.selAuthFormInfo = [];
    let aCnt = 0;
    if (document.authForm.authFormYn.length == null || document.authForm.authFormYn.length === 1) {
        if (document.authForm.authFormYn.checked === true) {
            scwin.selAuthFormInfo = document.authForm.authFormYn.value.split(',');
            scwin.selAuthFormCdList[0] = scwin.selAuthFormInfo[0];
            scwin.selAuthFormVerList[0] = scwin.selAuthFormInfo[1];
            aCnt++;
        }
    } else {
        if (document.authForm.authFormYn.length > 1) {
            for (let i = 0; i < document.authForm.authFormYn.length; i++) {
                if (document.authForm.authFormYn[i].checked === true) {
                    scwin.selAuthFormInfo = document.authForm.authFormYn[i].value.split(',');
                    scwin.selAuthFormCdList[aCnt] = scwin.selAuthFormInfo[0];
                    scwin.selAuthFormVerList[aCnt] = scwin.selAuthFormInfo[1];
                    aCnt++;
                }
            }
        }
    }
    return aCnt;
};

/**
 * @method
 * @name selAllFormCount
 * @description sel All Form Count 처리
 * @returns {void}
 * @hidden N
 */
scwin.selAllFormCount = function () {
    scwin.selFormList = [];
    let fCnt = 0;
    if ($c.util.getComponent('dlt_formLists').getRowCount() == null || $c.util.getComponent('dlt_formLists').getRowCount() === 1) {
        if (($c.util.getComponent('dlt_formLists').getRowCount() > 0).checked === true) {
            scwin.selFormList[0] = $c.util.getComponent('dlt_formLists').getCellData(0, 'allFormYn');
            fCnt++;
        }
    } else {
        if ($c.util.getComponent('dlt_formLists').getRowCount() > 1) {
            for (let i = 0; i < $c.util.getComponent('dlt_formLists').getRowCount(); i++) {
                if ((['true', 'Y', '1'].indexOf(String($c.util.getComponent('dlt_formLists').getCellData(i, 'allFormYn'))) >= 0)=== true) {
                    scwin.selFormList[fCnt] = $c.util.getComponent('dlt_formLists').getCellData(i, 'allFormYn');
                    fCnt++;
                }
            }
        }
    }
    return fCnt;
};

/**
 * @method
 * @name deleteAuthFormList
 * @description delete Auth Form List 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.deleteAuthFormList = async function () {
    const cnt = scwin.selAuthFormCount();
    const delChk = document.getElementsByName("authFormYn");
    let msgStr = "선택한 서식을 [권한 서식 List]에서[삭제] 합니다.\n";
    msgStr += "(※ 실제 서식 권한은 삭제되지 않습니다.)\n";
    msgStr += "===============================================\n";
    msgStr += " 권한 서식 List에서 삭제할 서식 건수 : [ " + cnt + " ] 건\n";
    msgStr += "===============================================\n\n";
    msgStr += "[권한 서식 List]에서 서식을 [삭제] 하시겠습니까?";
    if (await $c.win.confirm(msgStr)) {
        for (let i = 0; i < delChk.length; i++) {
            if (delChk[i].checked === true) {
                /* TODO Stage2: [sdd] 미실현 동작: delete_row (대상 미해석) — 전환 미완 */ /* unresolved-target intent:delete_row — {target}.deleteRow({args}) */
                i--;
            }
        }
    } else {
        await $c.win.alert("삭제를 취소합니다.");
        return;
    }
};

/**
 * @method
 * @name addAuthFormList
 * @description add Auth Form List 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.addAuthFormList = async function () {
    const cnt = scwin.selAllFormCount();
    const objTable = $c.util.getComponent("authFormTable");
    if (objTable == null) {
        await $c.win.alert("[권한 List]에서 권한을 선택하세요.");
        return;
    }
    let msgStr = "선택한 서식을 [권한 서식 List]에 추가합니다.\n";
    msgStr += "서식은 [권한 서식 List] 하단으로 추가됩니다.\n";
    msgStr += "===============================================\n";
    msgStr += " 서식 List에서 선택한 서식 건수 : [ " + cnt + " ] 건\n";
    msgStr += "===============================================\n\n";
    msgStr += "[권한 서식 List]에 서식을 [추가] 하시겠습니까?";
    if (await $c.win.confirm(msgStr)) {
        for (let i = 0; i < cnt; i++) {
            const objRow = objTable.insertRow();
            scwin.makeInnerHtml(objRow, scwin.selFormList[i]);
        }
        await $c.win.alert("[" + cnt + "] 건의 서식이 추가되었습니다.\n(※ [권한 서식 List] 하단을 확인하세요.)");
        return;
    } else {
        await $c.win.alert("서식 추가를 취소합니다.");
        return;
    }
};

/**
 * @method
 * @name makeInnerHtml
 * @description make Inner Html 처리
 * @param {*} objRow objRow
 * @param {String} arrStr arrStr
 * @returns {void}
 * @hidden N
 */
scwin.makeInnerHtml = function (objRow, arrStr) {
    const rowCnt = $c.util.getComponent("authFormTable").getElementsByTagName("tr").length;
    const valArr = arrStr.split(',');
    let clss = "";
    if (rowCnt % 2 === 1) {
        clss = "data_b";
    } else {
        clss = "data_a";
    }
    const td1 = objRow.insertCell();
    const td2 = objRow.insertCell();
    const td3 = objRow.insertCell();
    const td4 = objRow.insertCell();
    const td5 = objRow.insertCell();
    const td6 = objRow.insertCell();
    td1.className = clss;
    td2.className = clss;
    td3.className = clss;
    td4.className = clss;
    td5.className = clss + "t";
    td6.className = clss;
    const htmlStr1 = "<input type=\"checkbox\" name=\"authFormYn\" value=\"" + valArr[1] + "," + valArr[2] + "\" />";
    const htmlStr2 = valArr[0];
    const htmlStr3 = valArr[1];
    const htmlStr4 = valArr[2];
    const htmlStr5 = valArr[3];
    const htmlStr6 = valArr[4];
    td1.innerHTML = htmlStr1;
    td2.innerHTML = htmlStr2;
    td3.innerHTML = htmlStr3;
    td4.innerHTML = htmlStr4;
    td5.innerHTML = htmlStr5;
    td6.innerHTML = htmlStr6;
};

/**
 * @method
 * @name execAddAuth
 * @description exec Add Auth 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.execAddAuth = async function () {
    const cnt = scwin.selAuthFormCount();
    if (cnt < 1) {
        await $c.win.alert("선택된 서식이 없습니다.\n권한에 추가할 서식을 [권한 서식 List]에서 선택해주세요.");
        return;
    }
    let msgStr = "대상 권한에 서식 권한을 추가합니다.\n";
    msgStr += "===============================================\n";
    msgStr += " 대상 권한 : [" + $c.util.getComponent('dma_findContentXhrReq').get('formAuthNm') + "]\n";
    msgStr += " 권한 서식 List에서 선택한 서식 건수 : [ " + cnt + " ] 건\n";
    msgStr += "===============================================\n\n";
    msgStr += "[서식 추가]를 진행하시겠습니까?";
    if (await $c.win.confirm(msgStr)) {
        await scwin.addAuthForm($c.util.getComponent('dma_findContentXhrReq').get('formAuthId'));
        await $c.win.alert("[" + cnt + "] 건의 서식이 추가되었습니다.");
        return;
    } else {
        await $c.win.alert("[서식 추가]가 취소되었습니다.");
        return;
    }
};

/**
 * @method
 * @name addAuthForm
 * @description add Auth Form 처리
 * @param {String} formAuthId formAuthId
