    $c.util.getComponent('dma_findContentXhrReq').set('objFormCdList', scwin.selAuthFormCdList);
    $c.util.getComponent('dma_findContentXhrReq').set('objFormVerList', scwin.selAuthFormVerList);
    dataDiv = "authFormDiv";
    await scwin.tx_addAuthForm_xhr();
};

/**
 * @method
 * @name execDelAuth
 * @description exec Del Auth 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.execDelAuth = async function () {
    const cnt = scwin.selAuthFormCount();
    scwin.formAuthSearchYn = scwin.checkFormAuthSearchYn();
    if (scwin.formAuthSearchYn) {
        let msgStr = "대상 권한의 서식 권한을 삭제합니다.\n";
        msgStr += "(※ 실제 서식 권한이 삭제됩니다.)\n";
        msgStr += "===============================================\n";
        msgStr += " 대상 권한 : [" + $c.util.getComponent('dma_findContentXhrReq').get('formAuthNm') + "]\n";
        msgStr += " 권한 서식 List에서 선택한 서식 건수 : [ " + cnt + " ] 건\n";
        msgStr += "===============================================\n\n";
        msgStr += "[서식 삭제]를 진행하시겠습니까?";
        if (await $c.win.confirm(msgStr)) {
            await scwin.delAuthForm($c.util.getComponent('dma_findContentXhrReq').get('formAuthId'));
            await $c.win.alert("[" + cnt + "] 건의 서식이 삭제되었습니다.");
            return;
        } else {
            await $c.win.alert("[서식 삭제]가 취소되었습니다.");
            return;
        }
    } else {
        msgStr = "대상 권한과 조회된 권한 서식 List의 권한이 다릅니다. \n";
        msgStr += "===============================================\n";
        msgStr += " 대상 권한 : [" + $c.util.getComponent('dma_findContentXhrReq').get('formAuthNm') + "]\n";
        msgStr += " 조회된 권한 서식 List의 권한 : [ " + $(".copyAuthList option:selected").text() + " ]\n";
        msgStr += "===============================================\n";
        msgStr += "대상 권한과 조회된 권한 서식 List의 권한이 동일해야 삭제가 가능합니다.\n\n";
        await $c.win.alert(msgStr);
        return;
    }
};

