 */
scwin.delAuthForm = async function (formAuthId) {
    scwin.form_authFormForm.action = "/filing/byauthForm.do";
    $c.util.getComponent('dma_findContentXhrReq').set('method', "delAuthForm");
    $c.util.getComponent('dma_findContentXhrReq').set('formAuthId', formAuthId);
    $c.util.getComponent('dma_findContentXhrReq').set('objFormCdList', scwin.selAuthFormCdList);
    $c.util.getComponent('dma_findContentXhrReq').set('objFormVerList', scwin.selAuthFormVerList);
    dataDiv = "authFormDiv";
