/**
 * @method
 * @name viewAllFormList
 * @description view All Form List 처리
 * @param {String} listTp listTp
 * @returns {void}
 * @hidden N
 */
scwin.viewAllFormList = function (listTp) {
    let allEditChecked = null;
    let objChk = null;
    if (listTp === 'authForm') {
        scwin.allEditChecked = (document.authForm || { elements: [] }).allEdit1.checked;
        objChk = document.getElementsByName("authFormYn");
    } else {
        if (listTp === 'allForm') {
            allEditChecked = (String($c.util.getComponent('ipt_allEdit2').getValue() || "") !== "");
            objChk = document.getElementsByName("allFormYn");
        }
    }
    if (allEditChecked === true) {
        for (let i = 0; i < objChk.length; i++) {
            objChk[i].checked = true;
        }
    } else {
        for (let i = 0; i < objChk.length; i++) {
            objChk[i].checked = false;
        }
    }
};

/**
 * @method
 * @name onchngFunction
 * @description onchng Function 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onchngFunction = async function () {
    const formAuthId = $c.util.getComponent('dma_findContentXhrReq').get('formAuthId');
    const selectAuth = $(".copyAuthList option:selected").val();
    const selectAuthNm = $(".copyAuthList option:selected").text();
    let msgStr = "선택 권한의 권한서식 정보를 조회합니다.\n";
    msgStr += "===============================================\n";
    msgStr += " 선택 권한 : [" + selectAuthNm + "]\n";
    msgStr += "===============================================\n\n";
    msgStr += "조회하시겠습니까?";
    if (await $c.win.confirm(msgStr)) {
        scwin.formAuthSearchYn = false;
        if (formAuthId !== '') {
            await scwin.findAuthForm(selectAuth);
        } else {
            await $c.win.alert("권한 List를 먼저 선택하세요.");
            $(".copyAuthList option:first").attr("selected", "selected");
        }
    } else {
        await $c.win.alert("조회가 취소되었습니다.");
        return;
    }
};

