/**
 * @method
 * @name checkFormAuthSearchYn
 * @description check Form Auth Search Yn 처리
 * @returns {void}
 * @hidden N
 */
scwin.checkFormAuthSearchYn = function () {
    const formAuth = $c.util.getComponent('dma_findContentXhrReq').get('formAuthId');
    const selFormAuth = $(".copyAuthList option:selected").val();
    if (!scwin.formAuthSearchYn) {
        if (formAuth === selFormAuth) {
            return true;
        } else {
            return false;
        }
    } else {
        return true;
    }
};
